"use client";

import * as React from "react";
import { DayButton, DayPicker } from "react-day-picker";
import { Icon } from "@iconify/react";

import { cn } from "@/lib/utils";
import { buttonVariants } from "./button";
import { oxFace, focusRing } from "./_shared";

/** Props for the Calendar; every react-day-picker prop passes through. */
export type CalendarProps = React.ComponentProps<typeof DayPicker>;

const navButton = cn(
  buttonVariants({ variant: "ghost", size: "icon-sm" }),
  "aria-disabled:pointer-events-none aria-disabled:opacity-50",
);

const arrowIcons = {
  left: "solar:alt-arrow-left-linear",
  right: "solar:alt-arrow-right-linear",
  up: "solar:alt-arrow-up-linear",
  down: "solar:alt-arrow-down-linear",
} as const;

/** The month arrows and dropdown caret, drawn in Solar line glyphs. */
function CalendarChevron({
  orientation = "left",
  className,
}: {
  orientation?: keyof typeof arrowIcons;
  className?: string;
}) {
  return <Icon icon={arrowIcons[orientation]} aria-hidden="true" className={cn("size-4", className)} />;
}

/**
 * One day of the grid. A chosen day, and each end of a range, wears the oxblood
 * face of the primary Button; the days between sit on the pale oxblood mark.
 * Today reads in oxblood until it is chosen.
 */
function CalendarDayButton({ className, modifiers, ...props }: React.ComponentProps<typeof DayButton>) {
  const filled = modifiers.selected && !modifiers.range_middle;

  return (
    <DayButton
      modifiers={modifiers}
      data-slot="calendar-day"
      className={cn(
        className,
        modifiers.outside && "text-muted-foreground",
        modifiers.today && !modifiers.selected && "font-semibold text-(--primary-text)",
        modifiers.range_middle && "rounded-none bg-transparent text-(--mark-foreground) hover:bg-transparent",
        filled && cn(oxFace, "font-medium"),
        modifiers.disabled && "opacity-40",
      )}
      {...props}
    />
  );
}

/**
 * Margin Calendar: a month of 2rem days with a small corner. The month name
 * sits between two ghost arrows; a chosen day takes the oxblood face, and a
 * range runs on the oxblood tint between two oxblood ends.
 */
function Calendar({ className, classNames, showOutsideDays = true, components, ...props }: CalendarProps) {
  return (
    <DayPicker
      data-slot="calendar"
      showOutsideDays={showOutsideDays}
      className={cn("p-3", className)}
      classNames={{
        months: "relative flex flex-col gap-4 sm:flex-row",
        month: "flex flex-col gap-3",
        month_caption: "flex h-7 items-center justify-center",
        caption_label:
          "inline-flex items-center gap-1 text-sm font-semibold text-foreground [&_svg]:size-3.5 [&_svg]:text-muted-foreground",
        dropdowns: "flex items-center gap-2",
        dropdown_root:
          "relative inline-flex items-center rounded-md px-1.5 hover:bg-accent has-[:focus-visible]:ring-3 has-[:focus-visible]:ring-ring",
        dropdown: "absolute inset-0 cursor-pointer opacity-0",
        nav: "absolute inset-x-0 top-0 flex h-7 items-center justify-between",
        button_previous: navButton,
        button_next: navButton,
        month_grid: "w-full border-collapse",
        weekdays: "flex",
        weekday: "w-8 text-center text-xs font-medium text-muted-foreground",
        week: "mt-0.5 flex w-full",
        day: "relative size-8 p-0 text-center",
        day_button: cn(
          "inline-flex size-8 items-center justify-center rounded-md text-sm tabular-nums text-foreground",
          "transition-colors duration-fast ease-(--ease-out) hover:bg-accent",
          focusRing,
          "disabled:pointer-events-none",
        ),
        range_start: "rounded-s-md bg-(--mark)",
        range_middle: "bg-(--mark)",
        range_end: "rounded-e-md bg-(--mark)",
        outside: "text-muted-foreground",
        disabled: "opacity-40",
        hidden: "invisible",
        week_number: "w-8 text-xs text-muted-foreground",
        footer: "pt-3 text-sm text-muted-foreground",
        ...classNames,
      }}
      components={{
        Chevron: CalendarChevron,
        DayButton: CalendarDayButton,
        ...components,
      }}
      {...props}
    />
  );
}
Calendar.displayName = "Calendar";

export { Calendar };
